solution:
function solve(n) {
  const memo = {}
  function fib(k) {
    if (k < 2) return k // kasus dasar
    if (memo[k] !== undefined) return memo[k] // sudah ada
    memo[k] = fib(k - 1) + fib(k - 2)
    return memo[k]
  }
  return fib(n)
}
